css:
/* Shared match-number token — used in the table cell, bracket card header, and detail panel. Swiss: uppercase, tracked, tabular numerals, monochrome muted, square, no red. */
.mno{
  display:inline-block;
  font-size:var(--fs-3xs);
  font-weight:700;
  color:var(--muted);
  letter-spacing:.1em;
  text-transform:uppercase;
  font-variant-numeric:tabular-nums;
  white-space:nowrap;
  vertical-align:middle;
}
/* In the dense table, sit the short token a hair right of the stage-tag. */
td .mno{margin-left:var(--sp-2)}

/* Bracket card header strip: number hard-left (the anchor), round name right. */
.bk-num{
  display:flex;
  align-items:baseline;
  justify-content:space-between;
  gap:var(--sp-2);
  padding:var(--sp-1) var(--sp-3);
  border-bottom:1px solid var(--line);
  background:var(--panel);
}
.bk-num .mno{
  color:var(--ink);            /* card's own number is primary on the card — ink, not muted */
  letter-spacing:.12em;
}
.bk-num .bk-round{
  font-size:var(--fs-3xs);
  font-weight:600;
  text-transform:uppercase;
  letter-spacing:.08em;
  color:var(--muted);
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}
/* Final card already has a trophy header; tone its number strip to match. */
.final-card .bk-num{border-bottom-color:var(--line-strong)}
